// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeJump) public {
        vm.assume(timeJump > 0);
        vm.deal(address(this), amount);
        // Drive c through a public/external call: send ether to trigger fallback
        (bool success, ) = address(c).call{value: address(this).balance}("");
        if (!success) {
            // The call reverted, so pastBlockTime should not have changed
            assertTrue(c.pastBlockTime() == 0 || c.pastBlockTime() < block.timestamp);
        } else {
            // The call succeeded
            assertTrue(c.pastBlockTime() == block.timestamp);
        }
    }
}

